import json,base64
R=Path(__file__).resolve().parents[1]
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wildcraft · 融合标记与次数 v01</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#102017;color:#e2e9d8;font:16px/1.65 -apple-system,"PingFang SC",sans-serif}main{max-width:1250px;margin:auto;padding:30px 24px}h1{font-size:31px;margin:8px 0 12px}h2{font-size:21px;margin:10px 0}.tag{color:#dfb776;font-size:14px}.muted{color:#b2c5a8}p{margin:10px 0}.controls{display:flex;gap:14px;flex-wrap:wrap;padding:18px;background:#25372a;border:1px solid #4a5d46;border-radius:10px;margin:22px 0}label{display:flex;align-items:center;gap:7px;flex-wrap:wrap}select,input{background:#13251a;color:inherit;border:1px solid #6b7a63;border-radius:5px;font:inherit;padding:7px;max-width:100%;accent-color:#dab779}input[type=range]{width:150px}button{background:#2c4530;color:inherit;border:1px solid #6b7a63;border-radius:5px;padding:8px 13px;font:inherit;cursor:pointer;min-height:42px}button:disabled{opacity:.5;cursor:default}button:hover:not(:disabled){background:#3b553a}:focus-visible{outline:3px solid #e4bf78;outline-offset:3px}.samples{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}.stage{border:1px solid #495e43;background:#17251d;padding:18px;overflow:auto;border-radius:10px}#live{image-rendering:pixelated;display:block}.board{width:100%;height:auto;border-radius:10px}.notes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:22px 0}.card{padding:18px;border:1px solid #495e43;border-radius:10px;background:#25372a}.small{font-size:14px;color:#b2c5a8}a{color:#e4c78a}.links{display:flex;gap:18px;flex-wrap:wrap}@media(max-width:800px){.notes{grid-template-columns:1fr}main{padding:22px 14px}h1{font-size:27px}.controls{padding:14px}}</style><main><div class="tag">WILDCRAFT / F03-02 · v01 待审稿</div><h1>融合标记与剩余次数</h1><p class="muted">左上角标识别融合状态，悬停说明读取精确次数，保留右下数量与底部原版耐久。</p><div class="controls"><label>宿主<select id="host"><option value="sword">剑</option><option value="axe">斧</option><option value="shield">盾</option><option value="arrow">箭</option></select></label><label>材料<select id="material"><option value="stone">石头</option><option value="diamond">钻石</option><option value="feather">羽毛</option></select></label><label>状态<select id="phase"><option value="fused">已融合</option><option value="unfused">普通物品</option><option value="spent">耗尽解除</option><option value="returned">拆分后材料</option><option value="inactive">材料不可用</option></select></label><label>剩余次数<input id="uses" type="range" min="1" max="32" value="32"><span id="useLabel">32 / 32</span></label><label>显示倍率<select id="scale"><option value="1">1倍</option><option value="2" selected>2倍</option><option value="3">3倍</option></select></label><label>语言<select id="language"><option value="zh">中文</option><option value="en">English</option></select></label><label><input id="glint" type="checkbox">附魔区域示意</label></div><div class="samples" id="samples"></div><div class="stage"><canvas id="live" width="384" height="244" tabindex="0" role="img" aria-label="物品栏融合角标及悬停次数参考"></canvas></div><p class="small">移动到不同物品槽查看说明；聚焦画布后也可用方向键切换。两倍、三倍保持整数像素；窄窗口可横向滚动。</p><div class="samples"><button id="consume">审稿演示：消耗一次</button><button id="reset">重置示例</button></div><p id="description" class="muted" aria-live="polite"></p><div class="notes"><div class="card"><h2>状态与数量分开</h2><p>原生5×5角标放在槽位左上，物品数量保持右下。融合箭每份为1支，旁边的普通箭×64用于检查数量显示。</p></div><div class="card"><h2>剩余次数单独读取</h2><p>悬停显示实际1～32次，最后4次用文字颜色提醒。宿主耐久保持原版含义，次数不做第二条耐久条，也不烘焙进贴图。</p></div><div class="card"><h2>共享一张小图集</h2><p>保留原16与32符号，新增5px角标；三者合并到64×32透明图集。各宿主共用，不按材料类型重复制作。</p></div></div><h2>审稿总览</h2><canvas class="board" id="board" width="1200" height="1580" aria-label="融合标记与剩余次数审稿总览"></canvas><p class="small">本页为美术布局与交互模拟，不连接游戏。物品轮廓复用已采用F03-01参考；浏览器字体和附魔区域示意需要接入后用原版渲染复核。</p><div class="links"><a href="../source/fuse-status-atlas-64x32.aseprite">图集源稿</a><a href="../exports/fuse-status-atlas-64x32.png">图集PNG</a><a href="../README.md">制作说明</a></div><p class="small">2026-10-06 · F03-01已采用 · 本项待审，未接入 · 下一项：F03-03未知材料回退外观</p></main><script>const SPEC=__SPEC__,MESH=__MESH__,BACK={},ATLAS=__ATLAS__,LOCALES=__LANG__;</script><script>__NATIVE__</script><script>__UI__</script></html>'''
for k,v in [('__SPEC__',(R/'references/adopted-mount-spec.json').read_text()),('__MESH__',(R/'references/adopted-reference-meshes.json').read_text()),('__ATLAS__',json.dumps(data(R/'exports/fuse-status-atlas-64x32.png'))),('__LANG__',json.dumps({k:json.loads((R/'references'/(n+'.json')).read_text()) for k,n in [('zh','zh_cn'),('en','en_us')]},ensure_ascii=False)),('__NATIVE__',(R/'source/native-reference-renderer.js').read_text()),('__UI__',(R/'source/status-review.js').read_text())]:html=html.replace(k,v)
(R/'review/preview.html').write_text(html);print('Review page saved',len(html))
